  "Xác nhận xong: SL thực xuất của đơn gốc = SL thực nhận, hệ thống tạo đơn + phiếu gửi bù phần thiếu{a}.": "On confirm: the original order's shipped qty = received qty, and the system creates a make-up order + note for the missing qty{a}.",
