  "Đơn đồng bộ từ app Sửa chữa bảo hành — chỉ xem": "Order synced from the Warranty repair app — view only",
  "Công nợ hiện tại": "Current debt",
  "Công nợ đơn này": "Debt of this order",
  "Duyệt = cho phép KTV vượt trần công nợ. Sau khi duyệt, hệ thống tự kiểm tra tồn kho: đủ hàng → vào phiếu xuất, thiếu → chờ hàng.": "Approving lets the technician exceed the debt limit. The system then checks stock: in stock → added to a delivery note, short → waiting for stock.",
