  "KTV báo chưa nhận được tiền. Kế toán \"Xác nhận hủy phiếu\" (tiền tạm giữ trả lại quỹ) hoặc \"Từ chối\" để đẩy lại cho KTV xác nhận.": "The technician reports not receiving the money. Accounting can \"Confirm cancel\" (held money returns to the fund) or \"Reject\" to send it back for the technician to confirm.",
