  "Không tải được phiếu hoàn tiền.": "Could not load the refund slip.",
  "Kế toán hủy phiếu — tiền trả lại quỹ": "Accounting cancelled the slip — money returned to the fund",
  "Kế toán tạo": "Created by accounting",
  "Kế toán tạo phiếu hoàn tiền từ quỹ dư → tiền tạm giữ khỏi quỹ → KTV xác nhận đã nhận thì trừ hẳn; KTV từ chối thì Kế toán xác nhận hủy (tiền về lại quỹ) hoặc đẩy lại cho KTV.": "Accounting creates a refund slip from the surplus fund → the money is held out of the fund → once the technician confirms receipt it is deducted for good; if the technician rejects, accounting confirms the cancellation (money returns to the fund) or sends it back to the technician.",
  "Kế toán tạo phiếu, tạm giữ tiền khỏi quỹ": "Accounting created the slip and held the money out of the fund",
  "Kế toán từ chối, đẩy lại chờ KTV xác nhận": "Accounting rejected, sent back for technician confirmation",
  "Kế toán xác nhận hủy — tiền trả lại quỹ": "Accounting confirmed cancellation — money returned to the fund",
  "Phiếu hoàn tiền {a}": "Refund slip {a}",
  "Phiếu đã hủy — tiền tạm giữ đã trả lại quỹ.": "Slip cancelled — the held money has been returned to the fund.",
  "Số tiền hoàn": "Refund amount",
  "Số tiền được tạm giữ khỏi quỹ ngay (không còn tự trừ cho phiếu xuất). KTV xác nhận đã nhận thì trừ hẳn; hủy phiếu thì tiền trả lại quỹ.": "The amount is held out of the fund immediately (no longer used to pay delivery notes). Once the technician confirms receipt it is deducted for good; cancelling the slip returns it to the fund.",
  "Tiền đang được tạm giữ khỏi quỹ. KTV bấm \"Đã nhận tiền\" khi đã nhận được tiền Kế toán chuyển — phiếu hoàn tất; chưa nhận thì bấm \"Từ chối\".": "The money is being held out of the fund. The technician clicks \"Received\" once the money from accounting arrives — the slip is completed; if not received, click \"Reject\".",
