  "Mã này đang có hàng về (dự kiến {a}) — nên Tiếp nhận, chờ hàng về.": "Stock for this part is on the way (expected {a}) — accept and wait for arrival.",
  "Mã này đã có ticket đang chờ Mua hàng đặt — có thể chuyển Mua hàng để gộp đặt cùng.": "This part already has a ticket awaiting purchasing — send to Purchasing to order together.",
  "Ngày dự kiến có hàng *": "Expected arrival date *",
  "Người đặt đơn được báo mã EO + ngày dự kiến. Hàng về: Kho bấm \"Hàng đã về\" như thường lệ.": "The orderer is notified of the EO code + expected date. On arrival the warehouse presses \"Arrived\" as usual.",
  "Thông tin để Kho đánh giá": "Information for warehouse review",
  "Ticket chuyển sang Mua hàng đặt hàng (Mua hàng nhận thông báo). Khi Mua hàng báo đã đặt, ticket về chờ hàng về như sau khi Kho tiếp nhận; Kho vẫn xác nhận \"Hàng đã về\".": "The ticket goes to Purchasing to order (Purchasing is notified). Once ordered it waits for arrival as after warehouse acceptance; the warehouse still confirms \"Arrived\".",
