  "Đơn vượt trần công nợ — đã được duyệt": "Order over the credit limit — approved",
  "Đơn đang nằm trong phiếu chưa gửi Kế toán sẽ rời phiếu và mang theo tiền đã thanh toán. Ticket thiếu hàng mở ở bước “Chờ mua hàng” để bạn nhập mã EO + ngày dự kiến; Kho xác nhận hàng về như thường. KTV không tự hủy được đơn khi ticket đang xử lý.": "An order in a slip not yet sent to Accounting leaves the slip and keeps its paid money. A shortage ticket opens at “Awaiting purchase” for you to enter the EO code + expected date; Warehouse confirms arrival as usual. The technician cannot cancel while the ticket is being processed.",
  "Đơn đang soạn chưa được tạo. Bạn có muốn lưu lại thông tin này cho lần sau không?": "The order you are editing has not been created. Save it for next time?",
