  "Chưa có hướng dẫn nào. Bấm \"Thêm hướng dẫn\" để soạn câu trả lời mẫu cho các thắc mắc KTV hay hỏi.": "No guides yet. Click \"Add guide\" to write template answers for questions technicians often ask.",
