  "Giá phải trả tính theo tổng đặt trong ngày: dưới 200.000đ = giá niêm yết, 200.000–500.000đ = 70%, từ 500.000đ = giá KTV (linh kiện Đình tủ luôn 85%).": "The price you pay depends on your total ordered today: under 200,000đ = list price, 200,000–500,000đ = 70%, from 500,000đ = technician price (cabinet parts always 85%).",
