  "Bỏ chọn = chỉ tách đơn, cả 2 đơn vẫn chờ hàng.": "Uncheck = split only, both orders keep waiting for stock.",
  "Các phiếu này chưa được Kế toán chốt xong đơn xuất nên giá trị được cộng vào mức chiết khấu của đơn đặt mới — đặt thêm trước khi Kế toán chốt để hưởng chiết khấu cao hơn.": "These slips have not been finalized by Accounting yet, so their value counts toward the discount tier of new orders — order more before Accounting finalizes to get a higher discount.",
  "Hàng về ít hơn số lượng đặt? Tách phần đã về sang đơn mới (duyệt vào phiếu, chuyển Kế toán), phần còn thiếu tiếp tục chờ Kho.": "Received less than ordered? Split the received part into a new order (approved into a slip, sent to Accounting); the missing part keeps waiting for the Warehouse.",
  "Kho có {a}/{b}": "Stock {a}/{b}",
  "Kho công ty chỉ đủ một phần — hệ thống dừng tự duyệt hàng về cho mã này, chờ Kho / Kế toán chọn phương án (tách đơn hoặc chờ đủ).": "Company stock covers only part of it — auto-approval for this part is paused, waiting for Warehouse / Accounting to choose (split the order or wait for full stock).",
  "Kho công ty hiện có {a}/{b} chiếc cho đơn này. Đơn đang được ưu tiên nên hệ thống DỪNG tự duyệt hàng về cho mã này (kể cả đơn xếp sau) — chọn phương án: tách phần đã có để giao trước, hoặc giữ chờ đủ hàng.": "Company stock has {a}/{b} units for this order. This order has priority, so the system PAUSES auto-approval for this part (including orders queued after it) — choose: split to deliver what is available first, or keep waiting for full stock.",
  "Khách lẻ → tính giá niêm yết, không chiết khấu.": "Retail customer → list price, no discount.",
  "Linh kiện chưa có Giá KTV nên vẫn giữ giá niêm yết.": "This part has no Technician price yet, so the list price is kept.",
  "Linh kiện phân loại Đình tủ luôn giảm 15% (giá niêm yết × 85%), không phụ thuộc tổng đặt.": "Parts classified as Đình tủ always get 15% off (list price × 85%), regardless of the total ordered.",
