  "Đơn được tạo khi các phiếu trên còn chờ chuyển tiền / chờ Kế toán chốt đơn xuất nên giá trị của chúng được cộng dồn — công ty khuyến khích KTV gom đơn để hưởng mức chiết khấu cao hơn.": "This order was created while the slips above were still waiting for payment / Accounting finalization, so their value is added up — the company encourages technicians to combine orders for a higher discount.",
