  "\"Khách hàng đã chuyển khoản về công ty\" chỉ áp dụng cho đơn mua (có tiền thanh toán)": "\"Customer paid the company directly\" only applies to purchase orders (with payment)",
  "1 phiếu chỉ gom đơn cùng hình thức xuất hóa đơn (Không / HĐ - Không thu phí / HĐ - Có thu phí / HĐ - Xuất cho trạm) và cùng loại \"KH đã chuyển khoản về công ty\"": "One slip only groups orders with the same invoice type (None / Invoice - no fee / Invoice - with fee / Invoice - for station) and the same \"customer paid the company\" flag",
  "Chọn 1 hình thức xuất hóa đơn (đơn mua) để tích.": "Choose an invoice type (purchase order) to tick.",
  "KH chuyển khoản về công ty": "Customer paid company",
  "Khách hàng đã chuyển khoản về công ty": "Customer paid the company directly",
  "Phiếu có YÊU CẦU XUẤT HÓA ĐƠN": "Slip REQUIRES AN INVOICE",
  "Phiếu có yêu cầu xuất hóa đơn: {a}": "Slip requires an invoice: {a}",
  "Quỹ KH chuyển khoản": "Customer transfer fund",
  "Tiền Kế toán xác nhận vào Quỹ KH chuyển khoản (không vào quỹ của KTV); đơn chỉ dùng tiền trong quỹ này.": "Money confirmed by Accounting goes to the customer-paid invoice fund (not the technician fund); the order only uses money in this fund.",
  "Tiền vào Quỹ KH chuyển khoản, không vào quỹ của KTV": "Money goes to the customer-paid invoice fund, not the technician fund",
  "tiền xác nhận vào Quỹ KH chuyển khoản (không vào quỹ của KTV).": "confirmed money goes to the customer-paid invoice fund (not the technician fund).",
  "Đơn KH chuyển khoản đã có tiền trong Quỹ KH chuyển khoản — chưa hỗ trợ gán sang KH lẻ": "Customer-paid order already holds money in the customer-paid invoice fund — assigning to a retail customer is not supported yet",
  "Đơn khác hình thức xuất hóa đơn (hoặc khác \"KH đã chuyển khoản về công ty\") với phiếu này — mỗi hình thức 1 phiếu riêng": "Order has a different invoice type (or \"customer paid the company\" flag) from this slip — each type has its own slip",
  "Đơn tích \"Khách hàng đã chuyển khoản về công ty\" phải chọn 1 hình thức xuất hóa đơn": "Orders ticked \"Customer paid the company directly\" must choose an invoice type",
  "Đơn đang nằm trong phiếu đã gửi Kế toán — không đổi được hình thức xuất hóa đơn (phiếu tách theo hình thức hóa đơn)": "Order is in a slip already sent to Accounting — the invoice type cannot be changed (slips are split by invoice type)",
  "— Kế toán lưu ý xuất hóa đơn cho phiếu này.": "— Accounting: please issue an invoice for this slip.",
  "Còn phải chuyển (phiếu KH)": "Still to transfer (customer slips)",
  "Khoản chuyển tiền KH": "Customer transfers",
  "Số dư theo KTV": "Balance by technician",
  "Sổ quỹ KH": "Customer fund ledger",
  "Tiền khách hàng chuyển khoản về công ty cho đơn có yêu cầu xuất hóa đơn. Quỹ gắn theo KTV nhận hàng nhưng TÁCH RIÊNG quỹ cá nhân của KTV: chỉ trả cho phiếu KH chuyển khoản; đơn hủy / từ chối thì tiền về lại quỹ này.": "Money customers transferred to the company for orders requiring an invoice. The fund belongs to the receiving technician but is SEPARATE from the technician's own fund: it only pays customer-paid slips; cancelled / rejected orders return money to this fund.",
  "Tất cả KTV": "All technicians",
  "Tồn quỹ KH chuyển": "Customer-paid fund balance",
