  "(không ghi lý do)": "(no reason given)",
  "Bằng chứng chuyển tiền của bạn bị trả lại. Kế toán CHƯA ghi nhận số tiền này — hàng sẽ chưa được xuất cho tới khi bạn chuyển lại / bổ sung đúng.": "Your transfer proof was returned. Accounting has NOT recorded this amount — goods will not ship until you transfer again / add the correct proof.",
  "Bỏ {n} đơn khỏi phiếu": "Remove {n} orders from slip",
  "Chuyển tiền ngay →": "Transfer now →",
  "KTV này đang có phiếu cùng loại đề xuất nhưng THIẾU HÀNG, đang tách riêng:": "This technician has a slip of the same request type that is OUT OF STOCK, kept separate:",
  "Kiểm tra lại số tiền, tài khoản nhận, nội dung chuyển khoản theo lý do trên.": "Check the amount, receiving account and transfer note against the reason above.",
  "Lưu ý Kế toán": "Note for Accounting",
  "Mở phiếu → bỏ ảnh sai, tải ảnh chuyển khoản đúng (hoặc chuyển bổ sung phần còn thiếu) → bấm \"Đã chuyển\" để gửi Kế toán xác nhận lại.": "Open the slip → remove wrong images, upload the correct transfer image (or transfer the missing amount) → press \"Transferred\" to resend to Accounting.",
  "Phiếu chờ hàng": "Awaiting-stock slip",
  "Phiếu chờ hàng — tách riêng đơn kho thiếu hàng, đơn có hàng nằm ở phiếu khác": "Awaiting-stock slip — out-of-stock orders kept separate, in-stock orders are on another slip",
  "Quỹ dư của {a} còn": "Remaining balance of {a}:",
  "Quỹ KH chuyển khoản còn": "Customer-paid invoice fund remaining:",
  "Tách {n} đơn kho thiếu hàng ra 1 phiếu chờ hàng riêng?\n\nPhiếu này chỉ còn đơn có hàng để Kế toán xuất trước. Tiền cần chuyển được tính lại cho từng phiếu (phần đã chuyển thừa về quỹ và tự trừ cho phiếu kia).": "Move {n} out-of-stock orders to a separate awaiting-stock slip?\n\nThis slip keeps only in-stock orders so Accounting can ship them first. Amounts are recalculated per slip (any overpayment goes to the fund and is applied to the other slip).",
