  "{n} đơn chưa vào phiếu xuất (chờ duyệt / chờ hàng không cần chuyển tiền) — hệ thống tự gom vào phiếu khi đơn được duyệt.": "{n} orders are not on a slip yet (awaiting approval / awaiting stock without transfer) — they are added to a slip automatically once approved.",
